#!/usr/bin/env bash
# Tracked code must not cite .scratch/ paths: the local issue tracker is
# git-excluded (docs/agents/issue-tracker.md), so a citation inside shipped or
# executed code is a dead link in every fresh clone, CI run, and product
# worktree — an agent-written test once sent its reader there for the audit
# trail. Cite the upstream issue number instead; prose citations in docs/
# remain legal because those files are the tracker's index.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later
#
# Exit codes: 0 no citation found, 1 a scanned file cites .scratch/,
# 125 not applicable (not inside a git checkout).

set -u

ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  scratch refs (not inside a git checkout)\n'
    exit 125
}
cd "$ROOT" || exit 1

# Allowlist: files whose job is to operate on or validate the tracker itself,
# so the string .scratch/ is their mechanism, not a pointer for their reader.
allowed() {
    case "$1" in
        tests/check_*.sh|tests/run_*.sh|tests/verify_*.sh|tests/hooks/*)
            return 0 ;;
        tests/test_agent_docs.py)
            return 0 ;;  # asserts the tracker contract docs/agents/issue-tracker.md states
    esac
    return 1
}

# Vendored interpreters, bundled data, and submodule trees ship their own
# text; their .scratch mentions (if any) are nobody's contract here.
vendored() {
    case "$1" in
        python/python3/*|python/opencc/*|python/libchewing/*)
            return 0 ;;
    esac
    return 1
}

checked=0
bad=0
while IFS= read -r file; do
    allowed "$file" && continue
    vendored "$file" && continue
    checked=$((checked + 1))
    if grep -q '\.scratch/' "$file" 2>/dev/null; then
        printf 'cites git-excluded .scratch/: %s\n' "$file"
        bad=1
    fi
done < <(git ls-files -- python tests)

printf 'checked %d tracked file(s)\n' "$checked"
[ "$bad" -eq 0 ]
